create or replace function public.record_online_payment(p_order_id uuid, p_provider text, p_reference text, p_status text) returns public.online_orders language plpgsql security definer set search_path = public as $$ declare v_order public.online_orders; begin if p_status not in ('authorized','paid','failed','refunded') or length(trim(p_provider)) not between 1 and 80 or length(trim(p_reference)) not between 1 and 200 then raise exception 'online_payment_invalid_input' using errcode = '22023'; end if; select * into v_order from public.online_orders where id = p_order_id for update; if v_order.id is null then raise exception 'online_order_not_found' using errcode = 'P0002'; end if; if v_order.payment_reference is not null and v_order.payment_reference <> p_reference then raise exception 'online_payment_reference_conflict' using errcode = '23505'; end if; update public.online_orders set payment_provider = p_provider, payment_reference = p_reference, payment_status = p_status, status = case when p_status in ('failed','refunded') then 'cancelled' when p_status in ('authorized','paid') and status = 'pending' then 'accepted' else status end, updated_at = now() where id = p_order_id returning * into v_order; return v_order; end $$;
revoke all on function public.record_online_payment(uuid, text, text, text) from public, anon, authenticated; grant execute on function public.record_online_payment(uuid, text, text, text) to service_role;
